import{_ as e,o as t,c as r,a3 as i}from"./chunks/framework.WFmvnizL.js";const u=JSON.parse('{"title":"哪吒监控 V2 - 开源服务器监控与运维平台","titleTemplate":"官方文档","description":"哪吒监控 V2 官方文档：自托管多服务器监控、网站与端口探测、告警通知、Web 终端、文件管理、任务、DDNS、API 的安装配置和排障指南。","frontmatter":{"layout":"home","title":"哪吒监控 V2 - 开源服务器监控与运维平台","titleTemplate":"官方文档","description":"哪吒监控 V2 官方文档：自托管多服务器监控、网站与端口探测、告警通知、Web 终端、文件管理、任务、DDNS、API 的安装配置和排障指南。","hero":{"name":"哪吒监控 V2","text":"开源、自托管的服务器监控与运维平台","tagline":"用一个 Dashboard 连接多台 Agent，统一查看服务器状态、检查网站与网络服务、发送告警并执行授权运维。","image":"https://raw.githubusercontent.com/nezhahq/nezha/master/.github/brand.svg","actions":[{"theme":"brand","text":"预览","link":"https://qio.ng"},{"theme":"alt","text":"安装 Dashboard →","link":"/guide/dashboard.html"}]},"features":[{"title":"多服务器状态","details":"集中查看 Linux、Windows、macOS、OpenWRT、群晖等设备的在线状态、CPU、内存、磁盘、网络流量和可用系统指标。"},{"title":"服务探测与告警","details":"从指定 Agent 执行 HTTP GET、ICMP Ping 和 TCPing，观察可用性、延迟与证书状态，并通过通知组发送告警。"},{"title":"日常远程运维","details":"按权限使用 Web 终端、文件管理、定时与触发任务、DDNS、NAT、REST API 和可选 MCP。"},{"title":"自托管与开源","details":"Dashboard 与 Agent 均由 NezhaHQ 开源发布；数据、访问入口、用户、存储和集成由部署者自行控制。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1785844584000}'),h={name:"index.md"};function l(o,a,n,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h2 id="哪吒监控-v2-是什么" tabindex="-1">哪吒监控 V2 是什么？ <a class="header-anchor" href="#哪吒监控-v2-是什么" aria-label="Permalink to &quot;哪吒监控 V2 是什么？&quot;">​</a></h2><p>哪吒监控 V2（Nezha Monitoring V2）由一个集中式 <strong>Dashboard</strong> 和安装在被监控设备上的 <strong>Agent</strong> 组成。Agent 报告主机状态并执行分配的网络检查或授权任务；Dashboard 负责身份与权限、数据展示、服务监控、告警通知、API 和配置管理。</p><ul><li><a href="/guide/overview.html">产品概览：能力、受众与常见问题</a></li><li><a href="/guide/architecture.html">架构与数据流：Dashboard、Agent、存储和连接</a></li><li><a href="/guide/version-compatibility.html">版本与兼容性：V2、组件版本与 <code>/api/v1</code></a></li><li><a href="/guide/security.html">安全与隐私：生产部署检查清单</a></li></ul><h2 id="典型使用场景" tabindex="-1">典型使用场景 <a class="header-anchor" href="#典型使用场景" aria-label="Permalink to &quot;典型使用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>哪吒 V2 提供的入口</th></tr></thead><tbody><tr><td>多地域 VPS 与云服务器</td><td>集中在线状态、资源、流量、分组、告警和授权远程操作</td></tr><tr><td>网站与端口可用性</td><td>HTTP、Ping、TCP、延迟、丢包、HTTPS 证书状态和失败通知</td></tr><tr><td>家庭实验室、NAS 与小型团队</td><td>自托管 Dashboard、用户权限、公开或登录状态页、任务和文件操作</td></tr><tr><td>内部自动化与 AI 工具</td><td>带 scope 的 API Token、REST API，以及默认关闭的 MCP 入口</td></tr></tbody></table><p>如果你的主要目标是公开状态页、秒级深度可观测性、PromQL 生态或企业网络设备管理，请先阅读<a href="/guide/comparison.html">哪吒与 Uptime Kuma、Netdata、Prometheus/Grafana、Zabbix 的对比</a>。</p><h2 id="五步开始使用" tabindex="-1">五步开始使用 <a class="header-anchor" href="#五步开始使用" aria-label="Permalink to &quot;五步开始使用&quot;">​</a></h2><ol><li>阅读<a href="/guide/architecture.html">架构与数据流</a>，准备域名、端口、TLS 和备份位置。</li><li><a href="/guide/dashboard.html">安装 Dashboard</a>，登录后立即修改默认密码。</li><li><a href="/guide/agent.html">安装 Agent</a>，确认第一台服务器上线并能持续报告。</li><li>配置<a href="/guide/services.html">服务监控</a>和<a href="/guide/notifications.html">通知方式</a>。</li><li>上线前完成<a href="/guide/security.html">安全与隐私清单</a>，再逐步增加用户、API 和远程运维能力。</li></ol><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://github.com/nezhahq/nezha" target="_blank" rel="noreferrer">Dashboard 源码与 Release</a></li><li><a href="https://github.com/nezhahq/agent" target="_blank" rel="noreferrer">Agent 源码与 Release</a></li><li><a href="https://github.com/nezhahq/nezhahq.github.io" target="_blank" rel="noreferrer">文档源码与问题反馈</a></li><li><a href="https://t.me/nezhanews" target="_blank" rel="noreferrer">Telegram 中文通知频道</a></li><li><a href="https://t.me/nezhamonitoring" target="_blank" rel="noreferrer">Telegram 中文交流群</a></li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="哪吒监控-v2-能监控哪些系统" tabindex="-1">哪吒监控 V2 能监控哪些系统？ <a class="header-anchor" href="#哪吒监控-v2-能监控哪些系统" aria-label="Permalink to &quot;哪吒监控 V2 能监控哪些系统？&quot;">​</a></h3><p>官方安装与文档覆盖 Linux、Windows、macOS，并提供 OpenWRT、群晖等场景说明。具体指标取决于操作系统、权限、硬件和 Agent 配置。</p><h3 id="dashboard-和-agent-必须使用相同版本吗" tabindex="-1">Dashboard 和 Agent 必须使用相同版本吗？ <a class="header-anchor" href="#dashboard-和-agent-必须使用相同版本吗" aria-label="Permalink to &quot;Dashboard 和 Agent 必须使用相同版本吗？&quot;">​</a></h3><p>两者独立发布，版本号不要求完全一致，但升级前应分别阅读 Release Notes，并在少量节点验证。详见<a href="/guide/version-compatibility.html">版本与兼容性</a>。</p><h3 id="哪吒-v2-可以监控网站和-ssl-证书吗" tabindex="-1">哪吒 V2 可以监控网站和 SSL 证书吗？ <a class="header-anchor" href="#哪吒-v2-可以监控网站和-ssl-证书吗" aria-label="Permalink to &quot;哪吒 V2 可以监控网站和 SSL 证书吗？&quot;">​</a></h3><p>可以。HTTP GET 服务监控会检查 URL 可用性；HTTPS 目标还会检查证书状态。也可以使用 Ping 和 TCPing 观察网络与端口。</p><h3 id="数据是否必须上传到第三方云" tabindex="-1">数据是否必须上传到第三方云？ <a class="header-anchor" href="#数据是否必须上传到第三方云" aria-label="Permalink to &quot;数据是否必须上传到第三方云？&quot;">​</a></h3><p>不必须。Dashboard 与 Agent 可以自托管。只有启用 OAuth2、外部通知、DDNS、CDN 等集成时，相关请求才会发送到相应服务。</p><h3 id="为什么当前接口路径仍然是-api-v1" tabindex="-1">为什么当前接口路径仍然是 <code>/api/v1</code>？ <a class="header-anchor" href="#为什么当前接口路径仍然是-api-v1" aria-label="Permalink to &quot;为什么当前接口路径仍然是 `/api/v1`？&quot;">​</a></h3><p>API 路径版本与产品代际独立。哪吒当前产品是 V2，实际 REST API 继续使用 <code>/api/v1</code> 路径。不要自行改成 <code>/api/v2</code>。</p>',21)])])}const g=e(h,[["render",l]]);export{u as __pageData,g as default};
